//! Independent field checks from the linked Google documentation; no eligibility verdict.
use serde_json::Value;
pub const NOTE:&str="Optional Google field checks cover Product name/offer-or-rating presence and Offer/AggregateOffer pricing, BreadcrumbList items, and selected Article recommendations. Review/rating internals, merchant listings, other rich-result features, policy/visibility, image access and full JSON-LD reference expansion are not checked. Missing Article dates are not reported as required. No search eligibility guarantee. Rules reviewed 2026-10-18.";
pub const SOURCES:[&str;3]=["https://developers.google.com/search/docs/appearance/structured-data/product-snippet","https://developers.google.com/search/docs/appearance/structured-data/breadcrumb","https://developers.google.com/search/docs/appearance/structured-data/article"];
pub struct Issue{pub path:String,pub severity:&'static str,pub code:&'static str,pub term:String,pub message:String}
fn issue(rows:&mut Vec<Issue>,path:&str,severity:&'static str,code:&'static str,term:&str,message:&str){rows.push(Issue{path:path.into(),severity,code,term:term.into(),message:message.into()})}
fn present(value:Option<&Value>)->bool{value.is_some_and(|value|match value{Value::Null=>false,Value::String(text)=>!text.trim().is_empty(),Value::Array(values)=>values.iter().any(|value|present(Some(value))),Value::Object(values)=>!values.is_empty(),_=>true})}
fn text(value:Option<&Value>)->bool{value.is_some_and(|value|value.as_str().is_some_and(|text|!text.trim().is_empty())||value.get("@value").is_some_and(|value|text(Some(value))))}
fn reference(value:&Value)->bool{value.as_object().is_some_and(|object|object.contains_key("@id")&&object.keys().all(|key|key=="@id"||key=="@type"))}
fn values(value:&Value)->Vec<(String,&Value)>{match value{Value::Array(values)=>values.iter().enumerate().map(|(index,value)|(format!("/{index}"),value)).collect(),value=>vec![(String::new(),value)]}}
fn number(value:Option<&Value>)->bool{value.is_some_and(|value|value.as_f64().or_else(||value.as_str().and_then(|value|value.parse::<f64>().ok())).is_some_and(f64::is_finite))}
fn currency(value:Option<&Value>)->bool{value.and_then(Value::as_str).is_some_and(|value|value.len()==3&&value.bytes().all(|byte|byte.is_ascii_alphabetic()))}
fn has_type(value:&Value,kind:&str)->bool{match value.get("@type"){Some(Value::String(value))=>value.eq_ignore_ascii_case(kind),Some(Value::Array(values))=>values.iter().any(|value|value.as_str().is_some_and(|value|value.eq_ignore_ascii_case(kind))),_=>false}}
fn unvalidated(rows:&mut Vec<Issue>,path:&str,message:&str){issue(rows,path,"Warning","GOOGLE_UNVALIDATED","",message)}
fn required(rows:&mut Vec<Issue>,node:&Value,path:&str,key:&str){if !present(node.get(key)){issue(rows,&format!("{path}/{key}"),"Error","GOOGLE_REQUIRED_PROPERTY",key,"Required field is missing or empty for this checked Google feature")}}
fn offer(rows:&mut Vec<Issue>,node:&Value,path:&str){
 if reference(node){unvalidated(rows,path,"Referenced offer fields were not expanded; price requirements remain unvalidated");return}
 if !node.is_object(){issue(rows,path,"Error","GOOGLE_FIELD_SHAPE","offers","Offer must contain an object");return}
 if has_type(node,"AggregateOffer"){required(rows,node,path,"lowPrice");required(rows,node,path,"priceCurrency");if present(node.get("lowPrice"))&&!number(node.get("lowPrice")){issue(rows,&format!("{path}/lowPrice"),"Error","GOOGLE_FIELD_FORMAT","lowPrice","Expected a numeric amount with a decimal point if needed")}if present(node.get("priceCurrency"))&&!currency(node.get("priceCurrency")){issue(rows,&format!("{path}/priceCurrency"),"Error","GOOGLE_FIELD_FORMAT","priceCurrency","Expected a three-letter currency code; actual ISO currency membership is not checked")}return}
 if !has_type(node,"Offer"){unvalidated(rows,path,"Only explicitly typed Offer and AggregateOffer pricing is checked");return}
 let specification=node.get("priceSpecification");if specification.is_some_and(reference)&&!present(node.get("price")){unvalidated(rows,&format!("{path}/priceSpecification"),"Referenced price specification was not expanded");return}
 if specification.is_some_and(Value::is_array)&&!present(node.get("price")){unvalidated(rows,&format!("{path}/priceSpecification"),"Multiple or complex price specifications are outside these field checks");return}
 let price_path=if present(node.get("price")){format!("{path}/price")}else{format!("{path}/priceSpecification/price")};
 let price=node.get("price").filter(|value|present(Some(value))).or_else(||specification.and_then(|value|value.get("price")));
 if !present(price){issue(rows,path,"Error","GOOGLE_REQUIRED_ONE_OF","price | priceSpecification.price","Offer requires a recorded price or a nested priceSpecification.price")}else if !number(price){issue(rows,&price_path,"Error","GOOGLE_FIELD_FORMAT","price","Expected a numeric amount with a decimal point if needed")}
 let currency_path=if present(node.get("priceCurrency")){format!("{path}/priceCurrency")}else{format!("{path}/priceSpecification/priceCurrency")};
 let money=node.get("priceCurrency").filter(|value|present(Some(value))).or_else(||specification.and_then(|value|value.get("priceCurrency")));
 if !present(money){issue(rows,&format!("{path}/priceCurrency"),"Warning","GOOGLE_RECOMMENDED_PROPERTY","priceCurrency","Currency is recommended for Product snippets; merchant-listing rules are separate")}else if !currency(money){issue(rows,&currency_path,"Error","GOOGLE_FIELD_FORMAT","priceCurrency","Expected a three-letter currency code; actual ISO currency membership is not checked")}
}
fn product(rows:&mut Vec<Issue>,node:&Value){required(rows,node,"","name");if present(node.get("name"))&&!text(node.get("name")){if node.get("name").is_some_and(reference){unvalidated(rows,"/name","Referenced product name was not expanded")}else{issue(rows,"/name","Error","GOOGLE_FIELD_SHAPE","name","Product name must contain text")}}
 if !["offers","review","aggregateRating"].iter().any(|key|present(node.get(key))){issue(rows,"","Error","GOOGLE_REQUIRED_ONE_OF","offers | review | aggregateRating","Product snippet requires at least one offer, review or aggregate rating")}
 if let Some(offers)=node.get("offers").filter(|value|present(Some(value))){for(suffix,value)in values(offers){offer(rows,value,&format!("/offers{suffix}"))}if !present(node.get("review"))&&!present(node.get("aggregateRating")){issue(rows,"","Warning","GOOGLE_RECOMMENDED_PROPERTY","review | aggregateRating","Offers without a review or aggregate rating may receive a Product snippet warning")}}
 for key in ["review","aggregateRating"]{if present(node.get(key)){unvalidated(rows,&format!("/{key}"),"Review and rating contents are outside this Product field-check subset")}}
}
fn breadcrumb(rows:&mut Vec<Issue>,node:&Value){let Some(Value::Array(items))=node.get("itemListElement")else{issue(rows,"/itemListElement","Error","GOOGLE_FIELD_SHAPE","itemListElement","BreadcrumbList requires an array with at least two ListItems");return};if items.len()<2{issue(rows,"/itemListElement","Error","GOOGLE_REQUIRED_COUNT","itemListElement","Breadcrumb trail requires at least two ListItems")}
 for(index,item)in items.iter().enumerate(){let path=format!("/itemListElement/{index}");if reference(item){unvalidated(rows,&path,"Referenced ListItem fields were not expanded");continue}if !has_type(item,"ListItem"){issue(rows,&path,"Error","GOOGLE_FIELD_SHAPE","@type","Breadcrumb entries must be typed ListItem");continue}
  let position=item.get("position").and_then(|value|value.as_f64().or_else(||value.as_str().and_then(|value|value.parse::<f64>().ok())));if !position.is_some_and(|value|value.is_finite()&&value>0.0&&value.fract()==0.0){issue(rows,&format!("{path}/position"),"Error","GOOGLE_FIELD_FORMAT","position","Breadcrumb position must be a positive integer")}
  let target=item.get("item");if index+1<items.len(){required(rows,item,&path,"item")}
  if present(target)&&!text(target)&&!target.is_some_and(|value|text(value.get("@id"))){issue(rows,&format!("{path}/item"),"Error","GOOGLE_FIELD_SHAPE","item","Breadcrumb item must contain a URL string or an object with @id")}
  if !text(item.get("name"))&&!target.is_some_and(|value|text(value.get("name"))){issue(rows,&format!("{path}/name"),"Error","GOOGLE_REQUIRED_PROPERTY","name","Breadcrumb needs a name on the ListItem or its nested item object")}
 }
}
fn article(rows:&mut Vec<Issue>,node:&Value){for key in ["headline","image","author"]{if !present(node.get(key)){issue(rows,&format!("/{key}"),"Warning","GOOGLE_RECOMMENDED_PROPERTY",key,"Recommended Article field is missing; Article has no required properties")}}
 if let Some(authors)=node.get("author").filter(|value|present(Some(value))){for(suffix,author)in values(authors){let path=format!("/author{suffix}");if reference(author){unvalidated(rows,&path,"Referenced author fields were not expanded");continue}if !text(author.get("name")){issue(rows,&format!("{path}/name"),"Warning","GOOGLE_RECOMMENDED_PROPERTY","author.name","Author name is recommended on a Person or Organization object")}if !present(author.get("url"))&&!present(author.get("sameAs")){issue(rows,&path,"Warning","GOOGLE_RECOMMENDED_PROPERTY","author.url | author.sameAs","An author identity URL or sameAs is recommended")}}}
}
pub fn supported(kind:&str)->bool{["Product","BreadcrumbList","Article","NewsArticle","BlogPosting"].iter().any(|value|value.eq_ignore_ascii_case(kind))}
pub fn check(node:&Value)->Vec<Issue>{let mut rows=Vec::new();if has_type(node,"Product"){product(&mut rows,node)}if has_type(node,"BreadcrumbList"){breadcrumb(&mut rows,node)}if ["Article","NewsArticle","BlogPosting"].iter().any(|kind|has_type(node,kind)){article(&mut rows,node)}rows}
#[cfg(test)]mod tests{
 use super::*;use serde_json::json;
 #[test]fn nested_amount_path_and_integral_decimal_positions_are_not_misreported(){let rows=check(&json!({"@type":"Product","name":"מוצר","offers":{"@type":"Offer","priceSpecification":{"price":"broken","priceCurrency":"ils"}}}));assert!(rows.iter().any(|row|row.path=="/offers/priceSpecification/price"&&row.code=="GOOGLE_FIELD_FORMAT"));assert!(!rows.iter().any(|row|row.term=="priceCurrency"));let breadcrumb=check(&json!({"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1.0,"name":"בית","item":"https://e.test/"},{"@type":"ListItem","position":2,"name":"פריט"}]}));assert!(breadcrumb.is_empty());}
 #[test]fn product_required_fields_and_currency_severity_follow_feature_scope(){let missing=check(&json!({"@type":"Product"}));assert_eq!(missing.iter().filter(|row|row.severity=="Error").count(),2);let free=check(&json!({"@type":"Product","name":"מוצר","offers":{"@type":"Offer","price":0}}));assert!(!free.iter().any(|row|row.severity=="Error"));assert!(free.iter().any(|row|row.term=="priceCurrency"&&row.severity=="Warning"));}
 #[test]fn aggregate_offer_requires_currency_and_numeric_low_price(){let rows=check(&json!({"@type":"Product","name":"מוצר","offers":{"@type":"AggregateOffer","lowPrice":"12,3"}}));assert!(rows.iter().any(|row|row.term=="priceCurrency"&&row.severity=="Error"));assert!(rows.iter().any(|row|row.term=="lowPrice"&&row.code=="GOOGLE_FIELD_FORMAT"));}
 #[test]fn nested_price_specification_and_references_do_not_invent_missing_prices(){let nested=check(&json!({"@type":"Product","name":"מוצר","offers":{"@type":"Offer","priceSpecification":{"@type":"PriceSpecification","price":"19.90","priceCurrency":"ILS"}}}));assert!(!nested.iter().any(|row|row.severity=="Error"||row.term=="priceCurrency"));let referenced=check(&json!({"@type":"Product","name":"מוצר","offers":{"@id":"#offer"}}));assert!(!referenced.iter().any(|row|row.severity=="Error"));assert!(referenced.iter().any(|row|row.code=="GOOGLE_UNVALIDATED"));}
 #[test]fn breadcrumbs_last_item_url_is_optional_and_nested_item_name_is_accepted(){let rows=check(&json!({"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"item":{"@id":"https://e.test/","name":"בית"}},{"@type":"ListItem","position":"2","name":"פריט"}]}));assert!(rows.is_empty());let bad=check(&json!({"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":0}, {"@type":"ListItem","position":2,"name":"last"}]}));assert_eq!(bad.iter().filter(|row|row.severity=="Error").count(),3);}
 #[test]fn article_has_only_recommendations_and_no_mandatory_date_findings(){let rows=check(&json!({"@type":"NewsArticle"}));assert_eq!(rows.len(),3);assert!(rows.iter().all(|row|row.severity=="Warning"));assert!(!rows.iter().any(|row|row.term.contains("date")));let full=check(&json!({"@type":"Article","headline":"חדשות","image":"https://e.test/i.png","author":{"@type":"Person","name":"ישראל","sameAs":"https://e.test/person"}}));assert!(full.is_empty());}
 #[test]fn unsupported_review_contents_are_explicitly_unvalidated(){let rows=check(&json!({"@type":"Product","name":"מוצר","review":{"@type":"Review","author":{"name":"ישראל"},"positiveNotes":{}}}));assert!(!rows.iter().any(|row|row.severity=="Error"));assert!(rows.iter().any(|row|row.code=="GOOGLE_UNVALIDATED"&&row.path=="/review"));}
}
